 edit(book,fn){const w=structuredClone(world(book));if(T.opaque(book))throw new Error('Unrecognized legacy tree data is preserved. Export a backup before converting it.');w.trees=w.trees||[];fn(w.trees,w);T.validate(w);return {...book,world:w}},
