 update(book,id,patch){return T.edit(book,trees=>{const index=trees.findIndex(t=>t.id===id);if(index<0)throw new Error('Tree no longer exists.');const t={...trees[index],...patch,id,bookId:trees[index].bookId||book.id,updatedAt:Date.now()};if(!t.name?.trim()||!templates.includes(t.template))throw new Error('Enter a tree name and choose a template.');trees[index]=t})},
