 assign(book,id,characterId,rankId){const t=T.get(book,id);if(!t.memberIds.includes(characterId)||rankId&&!t.ranks.some(r=>r.id===rankId))throw new Error('Choose a member and valid rank.');return T.update(book,id,{assignments:{...t.assignments,[characterId]:rankId||null}})},
 connection(book,id,data,connectionId){const t=T.get(book,id);if(t.template!=='blank')throw new Error('Local connections belong to Blank Trees.');if(data.from===data.to||![data.from,data.to].every(x=>t.memberIds.includes(x)))throw new Error('Choose two different tree members.');const old=t.connections.find(c=>c.id===connectionId),connection={...old,...data,id:old?.id||crypto.randomUUID(),label:data.label?.trim()||'Connection'};return T.update(book,id,{connections:old?t.connections.map(c=>c.id===old.id?connection:c):[...t.connections,connection]})},
